/**
 * Render configuration — boundary contract for renderer, preferences (S04),
 * and routing pad highlighting (S03).
 *
 * Defines LOD tiers, layer colors, font sizing, and the pad-to-net lookup
 * that enables per-pad net highlighting.
 */

import type { NetInfo } from './types';

// ---------------------------------------------------------------------------
// LOD tiers
// ---------------------------------------------------------------------------

export enum LodTier {
  /** Shapes only, no text at all */
  Far = 0,
  /** Refdes labels + body outlines + drill marks */
  Medium = 1,
  /** Pad pin numbers + net labels on traces */
  Close = 2,
  /** Full detail — all annotations */
  Detail = 3,
}

// ---------------------------------------------------------------------------
// RenderConfig interface
// ---------------------------------------------------------------------------

export interface RenderConfig {
  layerColors: {
    topCopper: string;
    bottomCopper: string;
    silkscreen: string;
    via: string;
    drill: string;
  };

  fontConfig: {
    /** Refdes text size in nanometers (world-space). 800_000 = 0.8mm */
    refdesWorldSize: number;
    /** Minimum pad screen-pixel width before pin numbers are drawn */
    padNumberMinScreenPx: number;
    /** Minimum trace segment screen-pixel length before net labels are drawn */
    netLabelMinSegmentPx: number;
  };

  lodThresholds: {
    /** Scale above which we enter Medium tier (from Far) */
    medium: number;
    /** Scale above which we enter Close tier */
    close: number;
    /** Scale above which we enter Detail tier */
    detail: number;
  };
}

// ---------------------------------------------------------------------------
// Defaults factory
// ---------------------------------------------------------------------------

/**
 * Create a RenderConfig with sensible defaults.
 *
 * LOD thresholds are calibrated for the viewport's px/nm scale:
 * - scale 0.0001 = 1mm → 100px (default zoom)
 * - scale 0.00003 = 1mm → 30px (zoomed out)
 * - scale 0.0003 = 1mm → 300px (zoomed in)
 */
export function createDefaultRenderConfig(): RenderConfig {
  return {
    layerColors: {
      topCopper: '#C83434',
      bottomCopper: '#3434C8',
      silkscreen: '#C8C800',
      via: '#808080',
      drill: '#FFFFFF',
    },

    fontConfig: {
      refdesWorldSize: 800_000,        // 0.8mm
      padNumberMinScreenPx: 15,
      netLabelMinSegmentPx: 80,
    },

    lodThresholds: {
      medium: 0.000035,   // ~1mm = 35px — body outlines, refdes, drill marks
      close: 0.00008,     // ~1mm = 80px — pad numbers, net labels
      detail: 0.0002,     // ~1mm = 200px — everything, no culling
    },
  };
}

// ---------------------------------------------------------------------------
// LOD tier resolution
// ---------------------------------------------------------------------------

/**
 * Determine the LOD tier for a given viewport scale.
 */
export function getLodTier(scale: number, config: RenderConfig): LodTier {
  if (scale >= config.lodThresholds.detail) return LodTier.Detail;
  if (scale >= config.lodThresholds.close) return LodTier.Close;
  if (scale >= config.lodThresholds.medium) return LodTier.Medium;
  return LodTier.Far;
}

// ---------------------------------------------------------------------------
// Pad-to-net mapping
// ---------------------------------------------------------------------------

/**
 * Build a lookup from "refdes.pin" → net name using NetInfo.connections.
 *
 * Example: if net "VCC" has connection { component: "U1", pin: "1" },
 * the map will contain "U1.1" → "VCC".
 */
export function buildPadNetMap(nets: NetInfo[]): Map<string, string> {
  const map = new Map<string, string>();
  for (const net of nets) {
    if (!net.name) continue;
    for (const conn of net.connections) {
      const key = `${conn.component}.${conn.pin}`;
      map.set(key, net.name);
    }
  }
  return map;
}

import { describe, it, expect } from 'vitest';
import {
  createDefaultRenderConfig,
  getLodTier,
  buildPadNetMap,
  LodTier,
  type RenderConfig,
} from '../render-config';
import type { NetInfo } from '../types';

describe('createDefaultRenderConfig', () => {
  it('returns a valid config with all required fields', () => {
    const config = createDefaultRenderConfig();

    expect(config.layerColors).toBeDefined();
    expect(config.layerColors.topCopper).toBe('#C83434');
    expect(config.layerColors.bottomCopper).toBe('#3434C8');
    expect(config.layerColors.silkscreen).toBe('#C8C800');
    expect(config.layerColors.via).toBe('#808080');
    expect(config.layerColors.drill).toBe('#FFFFFF');

    expect(config.fontConfig.refdesWorldSize).toBeGreaterThan(0);
    expect(config.fontConfig.padNumberMinScreenPx).toBeGreaterThan(0);
    expect(config.fontConfig.netLabelMinSegmentPx).toBeGreaterThan(0);

    expect(config.lodThresholds.medium).toBeGreaterThan(0);
    expect(config.lodThresholds.close).toBeGreaterThan(config.lodThresholds.medium);
    expect(config.lodThresholds.detail).toBeGreaterThan(config.lodThresholds.close);
  });
});

describe('getLodTier', () => {
  const config = createDefaultRenderConfig();

  it('returns Far at very low scale', () => {
    expect(getLodTier(0.00001, config)).toBe(LodTier.Far);
  });

  it('returns Medium at medium scale', () => {
    // Just above medium threshold
    expect(getLodTier(config.lodThresholds.medium + 0.000001, config)).toBe(LodTier.Medium);
  });

  it('returns Close at close scale', () => {
    expect(getLodTier(config.lodThresholds.close + 0.000001, config)).toBe(LodTier.Close);
  });

  it('returns Detail at high scale', () => {
    expect(getLodTier(config.lodThresholds.detail + 0.000001, config)).toBe(LodTier.Detail);
  });

  it('returns exact boundary — medium threshold yields Medium', () => {
    expect(getLodTier(config.lodThresholds.medium, config)).toBe(LodTier.Medium);
  });

  it('returns exact boundary — close threshold yields Close', () => {
    expect(getLodTier(config.lodThresholds.close, config)).toBe(LodTier.Close);
  });

  it('returns exact boundary — detail threshold yields Detail', () => {
    expect(getLodTier(config.lodThresholds.detail, config)).toBe(LodTier.Detail);
  });

  it('returns Far at zero scale', () => {
    expect(getLodTier(0, config)).toBe(LodTier.Far);
  });
});

describe('buildPadNetMap', () => {
  it('maps multi-pin component correctly', () => {
    const nets: NetInfo[] = [
      {
        name: 'VCC',
        id: 1,
        connections: [
          { component: 'U1', pin: '1' },
          { component: 'C1', pin: '1' },
        ],
      },
      {
        name: 'GND',
        id: 2,
        connections: [
          { component: 'U1', pin: '4' },
          { component: 'C1', pin: '2' },
        ],
      },
    ];

    const map = buildPadNetMap(nets);
    expect(map.get('U1.1')).toBe('VCC');
    expect(map.get('C1.1')).toBe('VCC');
    expect(map.get('U1.4')).toBe('GND');
    expect(map.get('C1.2')).toBe('GND');
    expect(map.size).toBe(4);
  });

  it('handles empty nets array', () => {
    const map = buildPadNetMap([]);
    expect(map.size).toBe(0);
  });

  it('handles net with no connections', () => {
    const nets: NetInfo[] = [
      { name: 'FLOATING', id: 10, connections: [] },
    ];
    const map = buildPadNetMap(nets);
    expect(map.size).toBe(0);
  });

  it('skips nets with empty name', () => {
    const nets: NetInfo[] = [
      {
        name: '',
        id: 0,
        connections: [{ component: 'U1', pin: '1' }],
      },
    ];
    const map = buildPadNetMap(nets);
    expect(map.size).toBe(0);
  });

  it('handles power nets with standard names', () => {
    const nets: NetInfo[] = [
      {
        name: '+3V3',
        id: 5,
        connections: [
          { component: 'U1', pin: '14' },
          { component: 'U2', pin: '7' },
          { component: 'C3', pin: '1' },
        ],
      },
    ];

    const map = buildPadNetMap(nets);
    expect(map.get('U1.14')).toBe('+3V3');
    expect(map.get('U2.7')).toBe('+3V3');
    expect(map.get('C3.1')).toBe('+3V3');
    expect(map.size).toBe(3);
  });

  it('last-write wins when same pin appears in multiple nets (data error)', () => {
    // This shouldn't happen in valid data, but the function should not throw
    const nets: NetInfo[] = [
      { name: 'NET_A', id: 1, connections: [{ component: 'U1', pin: '1' }] },
      { name: 'NET_B', id: 2, connections: [{ component: 'U1', pin: '1' }] },
    ];
    const map = buildPadNetMap(nets);
    // Last net wins
    expect(map.get('U1.1')).toBe('NET_B');
    expect(map.size).toBe(1);
  });
});

