version 1

board blink {
    size 60mm x 40mm
    layers 2
}

component J1 connector "PIN-HDR-1x2" {
    value "5V PWR"
    at 5mm, 20mm
}

component U1 ic "SOIC-8" {
    value "NE555"
    at 28mm, 20mm
}

