import { test, expect } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

const BLINK_PATH = path.resolve(__dirname, '../../examples/blink.cypcb');

test.describe('Renderer Quality — Professional Visuals', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
  });

  test('canvas renders after loading blink.cypcb', async ({ page }) => {
    const content = fs.readFileSync(BLINK_PATH, 'utf-8');
    // Load via editor (toggle editor, set content)
    await page.locator('#editor-toggle').click();
    await page.waitForTimeout(500);
    // Use page.evaluate to load content directly through the engine
    await page.evaluate((src) => {
      // @ts-expect-error — global engine access
      const engine = (window as any).__pcbEngine;
      if (engine) {
        engine.load_source(src);
      }
    }, content);
    await page.waitForTimeout(500);

    const canvas = page.locator('#pcb-canvas');
    await expect(canvas).toBeVisible();
    const box = await canvas.boundingBox();
    expect(box).toBeTruthy();
    expect(box!.width).toBeGreaterThan(100);
  });

  test('__renderDiag exposes diagnostic surface', async ({ page }) => {
    // After initial render, the diagnostic surface should be set
    await page.waitForTimeout(300);
    const diag = await page.evaluate(() => (window as any).__renderDiag);
    expect(diag).toBeTruthy();
    expect(diag).toHaveProperty('lodTier');
    expect(diag).toHaveProperty('padNetMapSize');
    expect(diag).toHaveProperty('lastFrameMs');
    expect(diag).toHaveProperty('textElementsDrawn');
    expect(typeof diag.lodTier).toBe('number');
    expect(typeof diag.lastFrameMs).toBe('number');
  });

  test('component count matches snapshot after loading blink.cypcb', async ({ page }) => {
    const content = fs.readFileSync(BLINK_PATH, 'utf-8');
    await page.evaluate((src) => {
      const engine = (window as any).__pcbEngine;
      if (engine) {
        engine.load_source(src);
      }
    }, content);
    await page.waitForTimeout(500);

    const componentCount = await page.evaluate(() => {
      const engine = (window as any).__pcbEngine;
      if (!engine) return 0;
      const snap = engine.get_snapshot();
      return snap?.components?.length ?? 0;
    });

    // blink.cypcb has components (U1, R1, R2, C1, C2, D1, J1)
    expect(componentCount).toBeGreaterThanOrEqual(5);
  });

  test('padNetMap populated for blink.cypcb', async ({ page }) => {
    const content = fs.readFileSync(BLINK_PATH, 'utf-8');
    await page.evaluate((src) => {
      const engine = (window as any).__pcbEngine;
      if (engine) engine.load_source(src);
    }, content);
    await page.waitForTimeout(1000);

    const diag = await page.evaluate(() => (window as any).__renderDiag);
    expect(diag).toBeTruthy();
    // After loading a board with nets, padNetMapSize should be > 0
    expect(diag.padNetMapSize).toBeGreaterThan(0);
  });

  test('LOD tier changes with zoom level', async ({ page }) => {
    const content = fs.readFileSync(BLINK_PATH, 'utf-8');
    await page.evaluate((src) => {
      const engine = (window as any).__pcbEngine;
      if (engine) engine.load_source(src);
    }, content);
    await page.waitForTimeout(500);

    // Read LOD at default zoom
    const diagDefault = await page.evaluate(() => (window as any).__renderDiag);
    const defaultTier = diagDefault?.lodTier ?? -1;

    // Zoom in heavily (simulate scroll wheel)
    const canvas = page.locator('#pcb-canvas');
    const box = await canvas.boundingBox();
    if (box) {
      for (let i = 0; i < 15; i++) {
        await page.mouse.wheel(0, -120);
        await page.waitForTimeout(50);
      }
    }
    await page.waitForTimeout(300);

    const diagZoomed = await page.evaluate(() => (window as any).__renderDiag);
    const zoomedTier = diagZoomed?.lodTier ?? -1;

    // After zooming in, LOD tier should be same or higher
    expect(zoomedTier).toBeGreaterThanOrEqual(defaultTier);
  });
});
